//! Phase D — symbol parity between the C `.so` and the Rust `.so`.
//!
//! Enforces `SYMBOLS.md`: every symbol *defined* by the C shared object must
//! also be defined by the Rust shared object, under the exact same name.

mod common;

use common::*;

use std::collections::BTreeSet;
use std::path::Path;
use std::process::Command;

/// Names of all symbols that `nm -D` reports as *defined* (i.e. that carry an
/// address and whose type letter is not `U`/`w`/`v`).
fn defined_dynamic_symbols(so: &Path) -> BTreeSet<String> {
    let out = Command::new("nm")
        .args(["-D", "--defined-only", so.to_str().unwrap()])
        .output()
        .expect("run nm -D");
    assert!(
        out.status.success(),
        "nm failed on {}: {}",
        so.display(),
        String::from_utf8_lossy(&out.stderr)
    );
    String::from_utf8_lossy(&out.stdout)
        .lines()
        .filter_map(|line| {
            let mut it = line.split_whitespace();
            let a = it.next()?;
            let b = it.next()?;
            // "<addr> <type> <name>"; undefined/weak-undefined entries have no
            // address and therefore only two columns.
            let name = it.next()?;
            if a.chars().all(|c| c.is_ascii_hexdigit()) && b.len() == 1 {
                Some(name.to_string())
            } else {
                None
            }
        })
        .collect()
}

fn all_dynamic_symbols(so: &Path) -> BTreeSet<String> {
    let out = Command::new("nm")
        .args(["-D", so.to_str().unwrap()])
        .output()
        .expect("run nm -D");
    String::from_utf8_lossy(&out.stdout)
        .lines()
        .filter_map(|l| l.split_whitespace().last().map(|s| s.to_string()))
        .collect()
}

#[test]
fn c_defined_symbols_are_all_exported_by_rust() {
    let c_syms = defined_dynamic_symbols(&c_so_path());
    assert!(
        c_syms.contains("next_double"),
        "sanity: C .so must export next_double, got {c_syms:?}"
    );

    for profile in PROFILES {
        let r_syms = defined_dynamic_symbols(&rust_so_path(profile));
        let missing: Vec<&String> = c_syms.difference(&r_syms).collect();
        assert!(
            missing.is_empty(),
            "Rust .so ({profile}) is MISSING {} symbol(s) exported by the C .so: {missing:?}\n\
             C   defined: {c_syms:?}\n\
             {profile} defined: {r_syms:?}",
            missing.len()
        );
    }
}

#[test]
fn c_weak_boilerplate_symbols_also_present() {
    // The four weak/undefined toolchain symbols listed in SYMBOLS.md.
    let c_all = all_dynamic_symbols(&c_so_path());
    for profile in PROFILES {
        let r_all = all_dynamic_symbols(&rust_so_path(profile));
        let missing: Vec<&String> = c_all.difference(&r_all).collect();
        assert!(
            missing.is_empty(),
            "Rust .so ({profile}) does not reference {} symbol(s) the C .so does: {missing:?}",
            missing.len()
        );
    }
}

#[test]
fn every_c_symbol_is_callable_through_dlsym() {
    // A symbol that only *appears* in nm but traps/stubs when called would be
    // worse than a missing one, so actually invoke each exported function.
    for_each_pair(|c, r| {
        let mut rng = SplitMix64::new(SEED ^ 0xD1);
        for _ in 0..256 {
            assert_one(
                c,
                r,
                CnRnd::new(rng.next_u64(), rng.next_u64()),
                "symbol smoke test",
            );
        }
    });
}

#[test]
fn record_symbol_tables() {
    // Refresh the on-disk artifact referenced by SYMBOLS.md.
    let mut text = String::new();
    text.push_str("# generated by tests/symbol_parity.rs::record_symbol_tables\n");
    let mut entries: Vec<(String, std::path::PathBuf)> = vec![("C".to_string(), c_so_path())];
    for p in PROFILES {
        entries.push((format!("rust-{p}"), rust_so_path(p)));
    }
    for (label, path) in entries {
        text.push_str(&format!("\n## {label} ({})\n", path.display()));
        for s in defined_dynamic_symbols(&path) {
            text.push_str(&format!("DEFINED {s}\n"));
        }
    }
    let _ = std::fs::write(manifest_dir().join("rust_syms.txt"), text);
}
